export type Cell = [number, number];

function isNeighbor([x, y]: Cell, [otherX, otherY]: Cell): boolean {
  return Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1;
}

function countNeighbors(cell: Cell, liveCells: Cell[]): number {
  return liveCells.filter(
    (other) => other !== cell && isNeighbor(cell, other)
  ).length;
}

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter((cell) => countNeighbors(cell, liveCells) === 2);
}

