  it("Blinker: vertical [(0,0), (0,1), (0,2)] → horizontal [(-1,1), (0,1), (1,1)]", () => {
    expect(
      sorted(
        nextGeneration([
          [0, 0],
          [0, 1],
          [0, 2],
        ])
      )
    ).toEqual(
      sorted([
        [-1, 1],
        [0, 1],
        [1, 1],
      ])
    );
  });

